example_item.example_item_data:
% La page clinique douze derivations d'un enregistrement simule, en SVG calibre.
recording = ecglab.simulate('Seconds', 12, 'Rate', 500, 'Leads', 12, 'Seed', 1);
handle = ecglab.strip(recording, 'OutputImage', [tempdir(), '/ecg.svg']);

% Une seule derivation empilee sur dix secondes dans le style ecran sombre.
recording = ecglab.simulate('Seconds', 10, 'Rate', 360, 'Seed', 2);
ecglab.strip(recording, 'Layout', '1', 'Lead', 'II', 'Style', 'monitor');
